mapper.select:
SELECT t.tender_id, t.tender_code, t.tender_name, t.tender_type, t.tender_mode,
       t.budget_amount, t.currency, t.bid_start_time, t.bid_end_time, t.status,
       t.created_time,
       p.company_name as purchaser_name,
       pr.project_name,
       creator.account_display as created_by_name
FROM exp_tender t
LEFT JOIN exp_company p ON t.purchaser_id = p.company_id
LEFT JOIN exp_project pr ON t.project_id = pr.project_id
LEFT JOIN exp_account creator ON t.created_by = creator.account_id


        AND t.tender_code LIKE CONCAT('%', #{req.tenderCode}, '%')


        AND t.tender_name LIKE CONCAT('%', #{req.tenderName}, '%')


        AND t.tender_type = #{req.tenderType}


        AND t.tender_mode = #{req.tenderMode}


        AND t.purchaser_id = #{req.purchaserId}


        AND t.status = #{req.status}


        AND t.project_id = #{req.projectId}


        AND t.created_by = #{req.createdBy}


        AND t.bid_start_time >= #{req.bidStartTimeStart}


        AND t.bid_start_time <= #{req.bidStartTimeEnd}


        AND t.bid_end_time >= #{req.bidEndTimeStart}


        AND t.bid_end_time <= #{req.bidEndTimeEnd}


ORDER BY t.created_time DESC

SELECT COUNT(1)
FROM exp_tender
WHERE tender_code = #{tenderCode}

    AND tender_id != #{excludeTenderId}
